schuldrecht_geldpositionssumme <- function(regelfall=NULL, geldpositionen=NULL, einordnungsnachweis=NULL) {
 faelle <- list(ratenlieferung_nettobetragsersatz="\u00a7510III: Summe aller vom Verbraucher bis zum rechtlich fr\u00fchestm\u00f6glichen K\u00fcndigungszeitpunkt zu entrichtenden Teilzahlungen. Stichtag und Zahlungsplan extern qualifizieren; keine K\u00fcrzung auf aktuell offene Raten, bereits gezahlte zum Umfang geh\u00f6rende Raten bleiben enthalten. Keine Zahlungen erst nach dem ma\u00dfgeblichen Vertragsende einbeziehen. Ergebnis ersetzt nur die Bezugsgr\u00f6\u00dfe Nettodarlehensbetrag f\u00fcr491II2Nr1, entscheidet nicht weitere Ausnahmen oder Widerrufsrechte.",
ruecktritt_geldrueckgewaehr_einer_partei="\u00a7346: ausschlie\u00dflich rechtlich geschuldete Geldr\u00fcckgew\u00e4hr, Nutzungsherausgabe in Geld und Wertersatz einer bestimmten r\u00fcckgew\u00e4hrpflichtigen Vertragspartei. Sachr\u00fcckgabe nicht als zus\u00e4tzliche Geldforderung bewerten; Wertersatz tritt an die Stelle der betreffenden Sachr\u00fcckgabe. Kein doppeltes Erfassen von urspr\u00fcnglichem Geldbetrag, Ersatzwert und denselben Nutzungen. Wertersatzausnahmen346III und Bewertungsma\u00dfstab346II vorqualifiziert. Je Partei separat aufrufen; keine automatische Saldierung, Aufrechnung oder Durchbrechung von348.",
bereicherung_geldkomponenten="\u00a7818I/II: rechtlich zugeordnete Geldherausgabe, gezogene Nutzungen in Geld, erfasste Surrogate und an die Stelle nicht m\u00f6glicher Herausgabe tretender Wertersatz. Originalgegenstand und an seine Stelle tretenden Wertersatz/Surrogat nicht doppelt einrechnen; physische Sachherausgabe bleibt gesondert. Dies ist die Summe VOR gesonderter Entreicherungsbegrenzung818III, versch\u00e4rfter Haftung818IV/819/820 und Zahlungsanrechnung. Keine pauschale Addition beliebiger Ersatzanspr\u00fcche oder Rechtsgrundpr\u00fcfung.",
auftrag_geldherausgabe="\u00a7667: ausschlie\u00dflich Geldbetr\u00e4ge, die rechtlich aus dem zur Auftragsausf\u00fchrung Erhaltenen oder aus der Gesch\u00e4ftsbesorgung Erlangten herauszugeben sind. Nur unterschiedliche, noch nicht in anderen Positionen enthaltene Betr\u00e4ge; Sachherausgabe nicht in Geld umdeuten und denselben Verm\u00f6genswert nicht als Eingang und Surrogat doppelt z\u00e4hlen. Aufwendungsersatz670 und Vorsch\u00fcsse669 gesondert, keine automatische Saldierung oder Aufrechnung. Eigennutzungszinsen668 separat.",
mietmangel_schaden_und_selbstbeseitigung="\u00a7536aI/II: Summe rechtlich ersatzf\u00e4higer Geldsch\u00e4den und erforderlicher Selbstbeseitigungsaufwendungen aus demselben abgegrenzten Mangelkomplex. Anspruchsvoraussetzungen und jeweilige Schadensbemessung249ff vorqualifizieren. Jeder wirtschaftliche Nachteil nur einmal, auch bei mehreren Anspruchsgrundlagen; als Selbstbeseitigung enthaltene Reparatur nicht nochmals als Schaden addieren. Mietminderung536 und bereits geleisteter Ersatz separat, keine automatische Kumulation desselben Ausfalls.")
 .auswahl(regelfall,"regelfall",names(faelle))
 summe <- .rechnungssumme(geldpositionen,"geldpositionen")
 .text(einordnungsnachweis,"einordnungsnachweis")
 eingaben <- list(regelfall=regelfall, geldpositionen=geldpositionen, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .geld_ergebnis(summe,"BGB_SCHULDRECHT_GELDPOSITIONSSUMME",eingaben,list(list(operation="Qualifizierte \u00fcberschneidungsfreie Geldpositionen desselben gesetzlichen Berechnungsumfangs exakt summieren.")))
 ergebnis$hinweise <- c(ergebnis$hinweise,list("Nur numerischer Summenbaustein f\u00fcr den ausdr\u00fccklich gew\u00e4hlten Normfall. Bei510 werden alle bis zum fr\u00fchestm\u00f6glichen K\u00fcndigungszeitpunkt zu entrichtenden Raten erfasst, nicht nur offene. Bei346 je verpflichteter Partei getrennt; bei818 vor gesonderter Entreicherungs-/Haftungspr\u00fcfung. Keine automatische Aufrechnung, Sachbewertung oder Anspruchsentscheidung.",faelle[[regelfall]]))
 ergebnis
}
